  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The actual bracket, garage-floor bike inventory, and job-card process ground the concept in Mina’s particular work."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The actual bracket geometry and annotated detail views help visitors inspect her design changes."
    },
    "depth": {
      "result": "fail",
      "reason": "The independent project sections do not form a beginning, middle, and end that depend on one another."
    },
    "clipart": {
      "result": "pass",
      "reason": "The visual centrepiece is her actual pedal-box bracket rather than a generic engineering emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan qualifies the bracket result, credits the charger group, and omits unsupported achievements and repair counts."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The introduction and first visible project summary provide her name, student status, evidence of work, and direct contact access."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening identifies her plainly and describes credible work without inflated language."
    }
  },
  "copied_example": false,
